// Build a bounded repair plan. Emit zero items when there is no session or no gaps
// (downstream nodes then do not run, so the workflow is quiet). One HTTP call covers the
// union window of all gap symbols; genuine no-trade minutes simply come back empty and stay absent.
const r = $json.report;
if (!r || !r.session_id || !Array.isArray(r.gaps) || r.gaps.length === 0) return [];
const symbols = r.gaps.map(g => g.symbol);
const froms = r.gaps.map(g => new Date(g.from).getTime());
const tos = r.gaps.map(g => new Date(g.to).getTime());
// gap 'from'/'to' are bar_end values; Alpaca bars are keyed by bar start, so widen start by 1 min.
const start = new Date(Math.min(...froms) - 60000).toISOString();
const end = new Date(Math.max(...tos)).toISOString();
const d = new Date();
const due_window = `gap:${d.toISOString().slice(0,10)}:${d.getUTCHours()}:${Math.floor(d.getUTCMinutes()/5)*5}`;
return [{ json: {
  session_id: r.session_id,
  symbols,
  symbols_csv: symbols.join(','),
  start,
  end,
  due_window,
  owner: `wf08-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,
  token: Date.now(),
  total_missing: r.gaps.reduce((a,g) => a + Number(g.n), 0)
} }];

// Alpaca minute bars -> bar_versions rows. bar_end = bar start t + 1 min (matches the recorder).
// available_at/received_at default to now() in the DB: recovered data keeps its real recovery time,
// it is never backdated as if the live agent saw it. Only bars Alpaca actually returns are inserted.
const plan = $('Plan repair').first().json;
const sid = plan.session_id;
const rows = [];
for (const page of $input.all()) {
  const bars = (page.json && page.json.bars) || {};
  for (const [sym, arr] of Object.entries(bars)) {
    for (const b of arr) {
      const barEnd = new Date(new Date(b.t).getTime() + 60000).toISOString();
      rows.push({ session_id: sid, symbol: sym, bar_end: barEnd, open: b.o, high: b.h, low: b.l, close: b.c, volume: b.v, vwap: (b.vw ?? null), trade_count: (b.n ?? null) });
    }
  }
}
return [{ json: { rows, fetched: rows.length } }];

const plan = $('Plan repair').first().json;
const f = $('Flatten repaired bars').first().json;
return [{ json: { ok: true, symbols: plan.symbols.length, missing_detected: plan.total_missing, fetched: f.fetched, repaired: Number($json.repaired || 0), job_id: $json.job_id || null } }];
